-- ==============================================================================
-- PhantomTrace Flyway Migration V1 — Baseline schema
-- Establishes the persistence pattern for all subsequent domain entities.
-- UUIDs are generated by the application (Hibernate GenerationType.UUID),
-- so no DB-side default generator is required (keeps the migration portable).
-- ==============================================================================

-- Required extensions (also provisioned by infrastructure/database/init.sql
-- for Docker-managed instances; idempotent here for standalone Flyway runs).
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";

-- Analyst / user accounts.
CREATE TABLE users (
    id            UUID         PRIMARY KEY NOT NULL,
    email         VARCHAR(255) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    full_name     VARCHAR(150) NOT NULL,
    role          VARCHAR(50)  NOT NULL,
    created_at    TIMESTAMPTZ  NOT NULL,
    updated_at    TIMESTAMPTZ  NOT NULL
);

-- Explicit index for email lookups (login / duplicate checks).
CREATE INDEX idx_users_email ON users (email);
